// n8n Code node: validate the current PR snapshot and collect all file pages.
const before = $('Get PR Metadata').first().json;
const after = $input.first().json;
if (before.statusCode !== 200 || after.statusCode !== 200) throw new Error('PR 메타데이터 조회 실패');
const pr = before.body;
const latest = after.body;
const event = $('Github Trigger').first().json.body;
if (!pr.head?.sha || !pr.base?.sha || !pr.head?.repo?.full_name) throw new Error('PR 커밋 정보 누락');
if (pr.state !== 'open' || pr.base.ref !== 'dev') throw new Error('분석 대상 PR 상태가 변경됨');
if (event.pull_request?.head?.sha !== pr.head.sha) throw new Error('오래된 PR 이벤트: 최신 이벤트로 재실행 필요');
if (latest.head?.sha !== pr.head.sha || latest.base?.sha !== pr.base.sha || latest.changed_files !== pr.changed_files || latest.state !== pr.state || latest.base?.ref !== pr.base.ref) throw new Error('파일 조회 중 PR 변경: 다시 실행 필요');
const filesByPath = new Map();
for (const item of $('Get PR Files').all()) {
  const response = item.json;
  if (response.statusCode !== 200 || !Array.isArray(response.body)) throw new Error('PR 변경 파일 조회 실패');
  for (const file of response.body) {
    if (typeof file.filename !== 'string' || !file.filename || !['added','removed','modified','renamed','copied','changed','unchanged'].includes(file.status)) throw new Error('잘못된 변경 파일 데이터');
    if (filesByPath.has(file.filename)) throw new Error('중복 파일 페이지: 페이지 설정 확인 필요');
    filesByPath.set(file.filename, { filename: file.filename, previousFilename: file.previous_filename ?? null, status: file.status, additions: file.additions, deletions: file.deletions, patch: file.patch ?? null });
  }
}
const files = [...filesByPath.values()];
if (!Number.isInteger(pr.changed_files) || pr.changed_files < 0 || files.length !== pr.changed_files || pr.changed_files > 3000) throw new Error('변경 파일 수집 불완전: 리뷰 불필요로 처리할 수 없음');
return [{ json: { repository: 'prgrms-be-devcourse/NBE11-13-3-Team03', prNumber: pr.number, headSha: pr.head.sha, baseSha: pr.base.sha, headRepository: pr.head.repo.full_name, changedFileCount: files.length, hasChanges: files.length > 0, files } }];

// n8n Code node: Run Once for All Items. Input is the PR head's recursive Git tree.
const collected = $('Collect PR Files').first().json;
const response = $input.first().json;
if (response.statusCode !== 200 || !Array.isArray(response.body?.tree)) {
  throw new Error('PR 테스트 파일 목록 조회 실패');
}
const treeComplete = response.body.truncated === false;
const paths = response.body.tree.filter(e => e.type === 'blob').map(e => e.path);
const testPaths = paths.filter(p => /(^|\/)src\/test\/(java|kotlin)\/.+\.(java|kt)$/.test(p));
const reasons = new Set();
const domains = new Set();
const findings = [];
const rank = { LOW: 0, MEDIUM: 1, HIGH: 2 };
let risk = 'LOW';
let testRequired = false;
let testsChanged = false;
let newJavaFile = false;
let aiReviewRequired = false;
let docsOnly = true;
const raise = value => { if (rank[value] > rank[risk]) risk = value; };
const isDoc = p => /(^|\/)docs\//i.test(p) || /(^|\/)(readme|changelog|license)(\.[^/]*)?$/i.test(p) || /\.(md|mdx|rst|png|jpe?g|gif|webp|ico|svg)$/i.test(p);
for (const file of collected.files) {
  const names = [file.filename, file.previousFilename].filter(Boolean);
  const production = names.some(p => /(^|\/)src\/main\//.test(p));
  const source = names.some(p => /(^|\/)src\/main\/(java|kotlin)\/.+\.(java|kt)$/.test(p));
  const test = names.some(p => /(^|\/)src\/test\//.test(p));
  const build = names.some(p => /(^|\/)(build\.gradle(\.kts)?|settings\.gradle(\.kts)?|gradle\.properties|gradlew(\.bat)?|Dockerfile[^/]*|docker-compose[^/]*|compose\.ya?ml)$/.test(p) || /(^|\/)(\.github\/workflows|gradle\/wrapper)\//.test(p));
  const security = names.some(p => /(^|\/)(auth|security|oauth2?|jwt|token)(\/|\.)/i.test(p) || /(SecurityConfig|TokenProvider|Authentication|Authorization)/i.test(p));
  const high = production && names.some(p => /(service|controller|repository|purchase|inventory|sale|redis|scheduler|exception|\.lua$)/i.test(p));
  const doc = names.every(isDoc) && !production && !test && !build && !security;
  docsOnly &&= doc;
  for (const domain of ['auth','user','goods','sale','inventory','purchase','token','global','queue']) {
    if (names.some(p => new RegExp('(^|/)' + domain + '(/|\\.)','i').test(p))) domains.add(domain.toUpperCase());
  }
  if (security) { domains.add('SECURITY'); reasons.add('AUTH_SECURITY_CHANGED'); raise('HIGH'); }
  if (build) { domains.add('BUILD'); reasons.add('BUILD_CONFIG_CHANGED'); raise('MEDIUM'); }
  if (test) { testsChanged = true; reasons.add('TESTS_CHANGED'); }
  if (production) { testRequired = true; reasons.add('PRODUCTION_CHANGED'); raise(high ? 'HIGH' : 'MEDIUM'); }
  if (file.status === 'added' && /\.java$/.test(file.filename)) { newJavaFile = true; reasons.add('NEW_JAVA_FILE'); raise('MEDIUM'); }
  if (!doc && !test) { aiReviewRequired = true; raise('MEDIUM'); }
  if (security || build || production) aiReviewRequired = true;
  let matchingTests = [];
  let testStatus = 'NOT_APPLICABLE';
  if (source) {
    const candidates = names.map(p => p.match(/^(.*?)src\/main\/(?:java|kotlin)\/(.*)\.(?:java|kt)$/)).filter(Boolean);
    matchingTests = testPaths.filter(p => candidates.some(m => {
      return ['java','kotlin'].some(lang => ['Test','Tests','IntegrationTest','IT'].some(suffix =>
        p === `${m[1]}src/test/${lang}/${m[2]}${suffix}.${lang === 'java' ? 'java' : 'kt'}`));
    }));
    testStatus = matchingTests.length ? 'FOUND_BY_NAMING' : treeComplete ? 'NO_NAMING_MATCH' : 'UNKNOWN';
    if (!matchingTests.length) reasons.add(treeComplete ? 'RELATED_TEST_NOT_FOUND_BY_NAMING' : 'TEST_TREE_INCOMPLETE');
  }
  const addedLines = typeof file.patch === 'string' ? file.patch.split('\n').filter(l => l.startsWith('+') && !l.startsWith('+++')).map(l => l.slice(1)).join('\n') : null;
  const kotlinPatterns = /\.kt$/.test(file.filename) && addedLines !== null
    ? { nonNullAssertion: addedLines.includes('!!'), lateinit: /\blateinit\b/.test(addedLines) } : null;
  if (kotlinPatterns && (kotlinPatterns.nonNullAssertion || kotlinPatterns.lateinit)) { reasons.add('KOTLIN_RISK_PATTERN'); aiReviewRequired = true; raise('MEDIUM'); }
  if (!doc && !test && addedLines === null) reasons.add('PATCH_UNAVAILABLE');
  findings.push({ filename: file.filename, previousFilename: file.previousFilename, status: file.status, testStatus, matchingTests, kotlinPatterns, patchAvailable: addedLines !== null });
}
if (docsOnly) reasons.add('DOCS_ONLY');
if (!treeComplete) reasons.add('TEST_TREE_INCOMPLETE');
return [{ json: { analysisStatus: treeComplete ? 'COMPLETED' : 'PARTIAL', ...collected,
  domains: [...domains].sort(), risk, testsChanged, newJavaFile, testRequired, aiReviewRequired,
  docsOnly, testLookupComplete: treeComplete, reasons: [...reasons].sort(), findings,
  limitations: ['대응 테스트는 동일 패키지·클래스명 기반 후보 검색이며 테스트 내용·커버리지 검증이 아님', 'Kotlin 패턴은 추가된 diff 줄의 휴리스틱 검사이며 주석·문자열을 구분하지 않음', '포맷 전용·자동 생성 여부가 확실하지 않은 소스는 보수적으로 리뷰 대상으로 유지']
} }];

const analysis = $('Analyze PR Changes').first().json;
const pr = $('Get PR Metadata').first().json.body;
const event = $('Github Trigger').first().json.body;
const reviewTrigger = event?.action === 'opened' && event?.pull_request?.draft === false ? 'opened' : event?.action === 'synchronize' && event?.pull_request?.draft === false ? 'synchronize' : event?.action === 'ready_for_review' && event?.pull_request?.draft === false ? 'ready_for_review' : event?.action === 'labeled' && event?.label?.name === 'ai-review' ? 'ai-review' : null;
if (!reviewTrigger) return [{json:{status:'SKIPPED',reason:'EVENT_NOT_ALLOWED'}}];
if (pr.state !== 'open' || pr.base?.ref !== 'dev' || pr.head?.sha !== analysis.headSha) return [{json:{status:'SKIPPED',reason:'PR_CHANGED_BEFORE_REVIEW'}}];
if (reviewTrigger === 'ready_for_review' && pr.draft !== false) return [{json:{status:'SKIPPED',reason:'DRAFT_PR'}}];
const identity = $('Get Reviewer Identity').first().json;
if (analysis.aiReviewRequired !== true) return [{json:{status:'SKIPPED',reason:'AI_NOT_REQUIRED'}}];
if (identity.statusCode !== 200 || !identity.body?.id) return [{json:{status:'ERROR',reason:'IDENTITY_LOOKUP_FAILED'}}];
const marker = `<!-- gudit-ai-review:v1:${analysis.prNumber}:${analysis.headSha} -->`;
for (const item of $input.all()) {
  if (item.json.statusCode !== 200 || !Array.isArray(item.json.body)) return [{json:{status:'ERROR',reason:'COMMENT_LOOKUP_FAILED'}}];
  if (item.json.body.some(c => c.user?.id === identity.body.id && typeof c.body === 'string' && c.body.includes(marker))) return [{json:{status:'SKIPPED',reason:'ALREADY_COMMENTED',marker}}];
}
const selected = analysis.files.filter(f => ![f.filename,f.previousFilename].filter(Boolean).every(p => /^(docs\/)|\.(md|png|jpe?g|gif|webp|ico)$/i.test(p)));
const score = f => {
  const path = String(f.filename || '').toLowerCase(); let value = 0;
  if (/(^|\/)(auth|security|oauth2?|jwt|token)(\/|\.)/.test(path)) value += 100;
  if (/src\/main\//.test(path)) value += 60;
  if (/(service|controller|repository|transaction|inventory|purchase|sale|redis)/.test(path)) value += 50;
  if (/(build\.gradle|settings\.gradle|gradle\.properties|\.github\/workflows|docker|compose|application[^/]*\.ya?ml)/.test(path)) value += 40;
  if (/src\/test\//.test(path)) value += 20;
  if (f.status === 'added') value += 5;
  return value;
};
const utf8Slice = (value, maxBytes) => {
  let out = '', used = 0;
  for (const char of String(value)) { const size = Buffer.byteLength(char, 'utf8'); if (used + size > maxBytes) break; out += char; used += size; }
  return out;
};
const candidates = selected.filter(f => typeof f.patch === 'string' && f.patch.length > 0)
  .sort((a,b) => score(b) - score(a) || a.filename.localeCompare(b.filename));
const files = []; let diffBytes = 0;
for (const file of candidates) {
  if (files.length >= 20 || diffBytes >= 32000) break;
  const patch = utf8Slice(file.patch, Math.min(5000, 32000 - diffBytes));
  if (!patch) continue;
  const bytes = Buffer.byteLength(patch, 'utf8');
  files.push({filename:file.filename,status:file.status,patch,patchTruncated:bytes < Buffer.byteLength(file.patch,'utf8')});
  diffBytes += bytes;
}
if (!files.length) return [{json:{status:'SKIPPED',reason:'NO_REVIEWABLE_PATCH'}}];
const included = new Set(files.map(f => f.filename));
const analysisFindings = (analysis.findings || []).filter(f => included.has(f.filename));
const payload = {repository:analysis.repository,prNumber:analysis.prNumber,headSha:analysis.headSha,aiReviewRequired:true,marker,
  reviewTrigger,title:String(pr.title ?? '').slice(0,200),description:String(pr.body ?? '').slice(0,1500),
  analysis:{risk:analysis.risk,domains:analysis.domains,reasons:analysis.reasons,findings:analysisFindings},
  files,omittedPatchFiles:selected.filter(f => !included.has(f.filename) || typeof f.patch !== 'string' || !f.patch.length).map(f=>f.filename),
  inputStats:{changedFileCount:analysis.changedFileCount,selectedFileCount:files.length,diffBytes}};
const serialized = JSON.stringify(payload);
const inputBytes = Buffer.byteLength(serialized,'utf8');
if (inputBytes > 70000 || files.length > 20) return [{json:{status:'SKIPPED',reason:'INPUT_TOO_LARGE',marker,inputStats:payload.inputStats}}];
const encoded = Buffer.from(serialized,'utf8').toString('base64');
if (encoded.length > 120000 || !/^[A-Za-z0-9+/=]+$/.test(encoded)) return [{json:{status:'ERROR',reason:'INVALID_ENCODING'}}];
return [{json:{status:'RUN',marker,prNumber:analysis.prNumber,headSha:analysis.headSha,reviewTrigger,inputStats:payload.inputStats,
  command:"/usr/bin/python3 /root/ai-workflow/reviewer/reviewer.py '"+encoded+"'"}}];
